/* @autogenerated */
import { Shift, Projected } from '@shared/data/repository/repository.model';
import { ListViewCardTemplate, ListViewRowTemplate } from '@shared/toolkit/list-view/list-view.directives';
import {
  TemplateAssetFilter,
  TemplateAssetTypes,
} from 'app/features/template/template-asset/model/template-asset.model';
import { TemplateAssetRepository } from 'app/features/template/template-asset/repository/template-asset-repository.service';
import { FormControl } from '@angular/forms';
import { contentChild, input, effect, Component, signal } from '@angular/core';
import { DisplayProvider } from '@shared/data/display-provider';

@Component({
  selector: 'template-asset-view-list',
  templateUrl: './template-asset-view-list.component.html',
  styleUrls: ['./template-asset-view-list.component.scss'],
  standalone: false,
})
export class TemplateAssetViewListComponent {
  filters = input<TemplateAssetFilter>();
  actionName = input<string>('template-asset');
  fixed = input<{ [key: string]: any }>();
  hidden = input<{ [key: string]: any }>();
  /** Estructura de fila o tarjeta que pasa quien usa el listado (`<list-view-row>`/`<list-view-card>` como contenido). */
  rowLayout = contentChild(ListViewRowTemplate);
  cardLayout = contentChild(ListViewCardTemplate);
  search = new FormControl<any>(undefined);
  showSearchLabel = signal('Refresh');
  hideSearchLabel = signal('Refresh');
  readonly list: Shift<Projected<TemplateAssetTypes, 'template' | 'tenant'>[], TemplateAssetFilter>;
  readonly displayer: DisplayProvider<any>;
  refreshDataLabel = signal('Refresh');
  /** Último filtro buscado, sin paginación: lo usa la exportación. */
  query = signal<TemplateAssetFilter>({});

  constructor(repository: TemplateAssetRepository) {
    this.displayer = repository.displayProvider();
    this.list = repository.projections(['template', 'tenant']);
    effect(() => {
      setTimeout(() => this.makeSearch());
    });
  }
  makeSearch() {
    const result = { limit: 10 } as any;
    const filter = this.search.value;
    const external = this.filters();
    if (external?.search) {
      result.search = external.search;
    }
    if (external?.code) {
      result.code = external.code;
    }
    if (external?.template) {
      result.template = external.template;
    }
    if (external?.templates) {
      result.templates = external.templates;
    }
    if (external?.tenant) {
      result.tenant = external.tenant;
    }
    if (external?.tenants) {
      result.tenants = external.tenants;
    }
    if (filter?.search) {
      result.search = filter.search;
    }
    if (filter?.code) {
      result.code = filter.code;
    }
    if (filter?.template?.$ref) {
      result.template = filter.template.$ref;
    }
    if (filter?.templates?.$ref) {
      result.templates = filter.templates.$ref;
    }
    if (filter?.tenant?.$ref) {
      result.tenant = filter.tenant.$ref;
    }
    if (filter?.tenants?.$ref) {
      result.tenants = filter.tenants.$ref;
    }
    if (filter?.order) {
      result.order = filter.order;
    }
    const { limit, ...query } = result;
    this.query.set(query);
    this.list.fetch(result);
  }

  next() {
    this.list.next();
  }

  reload() {
    this.list.reset();
  }

  prev() {
    console.log('PREV');
  }
}
